declare const DEFAULT_MAX_DEPTH = 100;
interface LoadOptions {
    maxDepth?: number;
}
declare const load: (toml: string, options?: LoadOptions) => Record<string, unknown>;

declare class SyntaxParseError extends Error {
    constructor(message: string);
}

interface DumpOptions {
    /**
     * The newline sequence.
     * @default '\n'
     */
    newline?: '\n' | '\r\n';
    /**
     * If true, properties with unsupported types (like undefined, Symbol, Function)
     * will be silently ignored instead of throwing an error.
     * @default false
     */
    ignoreUndefined?: boolean;
    /**
     * If true, string keys will always be quoted, even when they contains only
     * bare-key characters.
     * @default false
     */
    forceQuotes?: boolean;
}

declare function dump(obj: Record<string, unknown>, options?: DumpOptions): string;

export { DEFAULT_MAX_DEPTH, type LoadOptions, SyntaxParseError, dump, load };
